mapper.select:
SELECT m.movement_id AS id, m.material_id AS product_id, m.location_id AS warehouse_id, CASE m.movement_type WHEN 'IN' THEN 'in' WHEN 'OUT' THEN 'out' ELSE 'check' END AS operation_type, NULL::numeric AS before_stock, m.balance_after AS after_stock, m.change_qty AS change_amount, m.source_ref AS remark, NULL::bigint AS operator_id, m.create_time FROM inventory_movement m WHERE 1=1
AND m.material_id = #{productId}
AND m.location_id = #{warehouseId}
AND CASE m.movement_type WHEN 'IN' THEN 'in' WHEN 'OUT' THEN 'out' ELSE 'check' END = #{operationType}
AND m.operator_id = #{operatorId}
AND m.create_time >= #{startTime}::timestamp
AND m.create_time <= #{endTime}::timestamp
ORDER BY m.create_time DESC
